// HasCa applies the HasEdge predicate on the "ca" edge.
func HasCa() predicate.Certificate {
	return predicate.Certificate(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CaTable, CaColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCaWith applies the HasEdge predicate on the "ca" edge with a given conditions (other predicates).
func HasCaWith(preds ...predicate.CA) predicate.Certificate {
	return predicate.Certificate(func(s *sql.Selector) {
		step := newCaStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

